import React, { useState } from 'react';

const SignUp = ({ onSignUpSuccess }) => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [errorMessage, setErrorMessage] = useState('');
    const [successMessage, setSuccessMessage] = useState('');
    const [isSigningUp, setIsSigningUp] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (password !== confirmPassword) {
            setErrorMessage('Passwords do not match');
            return;
        }

        try {
            console.log('🚀 Sending sign-up request...');

            const response = await fetch('/api/signup', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ username, password }),
            });

            console.log('📨 Response received:', response);

            const data = await response.json();

            if (response.ok) {
                console.log('✅ Sign-up successful:', data);

                setErrorMessage('');
                setSuccessMessage('Account created successfully! Logging you in...');

                // Automatically log in the user after sign-up
                await loginUserAfterSignup(username, password);
            } else {
                console.error('❌ Sign-up failed:', data);
                setErrorMessage(data.error || 'Failed to create account.');
            }
        } catch (error) {
            console.error('❌ Error during sign-up:', error);
            setErrorMessage('An error occurred. Please try again.');
        }
    };

    // Function to log the user in immediately after signing up
    const loginUserAfterSignup = async (username, password) => {
        try {
            console.log('🔑 Attempting to log in automatically...');

            const loginResponse = await fetch('/api/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ username, password }),
            });

            const loginData = await loginResponse.json();

            if (loginResponse.ok) {
                console.log('✅ Auto-login successful:', loginData);

                // Call the success callback with token & username
                onSignUpSuccess(loginData.token, username);
            } else {
                console.error('❌ Auto-login failed:', loginData);
                setErrorMessage('Sign-up successful, but auto-login failed. Please log in manually.');
            }
        } catch (error) {
            console.error('❌ Error during auto-login:', error);
            setErrorMessage('Sign-up successful, but auto-login failed. Please log in manually.');
        }
    };

    return (
        <div style={styles.container}>
            <h2 style={styles.heading}>Sign Up</h2>
            <form onSubmit={handleSubmit} style={styles.form}>
                <input
                    type="text"
                    placeholder="Username"
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    required
                    style={styles.input}
                />
                <input
                    type="password"
                    placeholder="Password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    style={styles.input}
                />
                <input
                    type="password"
                    placeholder="Confirm Password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    required
                    style={styles.input}
                />
                <button type="submit" style={styles.button}>Sign Up</button>
            </form>
            {errorMessage && <p style={styles.error}>{errorMessage}</p>}
            {successMessage && <p style={styles.success}>{successMessage}</p>}
            <button
                onClick={() => setIsSigningUp((prev) => !prev)}
                style={{ marginTop: '20px' }}
            >
                {isSigningUp
                    ? 'Already have an account? Log in'
                    : "Don't have an account? Sign Up"}
            </button>
        </div>
    );
};

const styles = {
    container: {
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        height: '100vh',
        backgroundColor: '#f9f9f9',
    },
    heading: {
        fontSize: '24px',
        marginBottom: '20px',
        fontWeight: 'bold',
    },
    form: {
        display: 'flex',
        flexDirection: 'column',
        width: '500px',
        height: '300px',
        padding: '20px',
        backgroundColor: 'white',
        boxShadow: '0px 4px 6px rgba(0, 0, 0, 0.1)',
        borderRadius: '8px',
    },
    input: {
        marginBottom: '15px',
        padding: '15px',
        width: '95%',
        border: '1px solid #ccc',
        borderRadius: '5px',
        fontSize: '18px',
    },
    button: {
        padding: '10px',
        backgroundColor: '#4CAF50',
        color: 'white',
        border: 'none',
        borderRadius: '5px',
        fontSize: '16px',
        cursor: 'pointer',
        marginTop: '10px',
    },
    error: {
        color: 'red',
        marginTop: '10px',
    },
    success: {
        color: 'green',
        marginTop: '10px',
    },
    loginButton: {
        marginTop: '15px',
        backgroundColor: 'transparent',
        border: 'none',
        color: '#007bff',
        cursor: 'pointer',
        fontSize: '14px',
    }
};

export default SignUp;
